/// <reference lib="webworker" />
import { loadLibFiles } from "./libs";
import { LIB_BUNDLE_URL, LIB_FILES } from "./options";
import type { CompilerRequest, CompilerResponse } from "./protocol";
import { createCompilerService, type CompilerService } from "./typescript";

declare const self: DedicatedWorkerGlobalScope;

/**
 * The lib .d.ts files are a static, versioned JSON asset generated by
 * scripts/prepare-assets.mjs (bundler-independent and cached immutably).
 */
const libBundle: Promise<Record<string, string>> = fetch(LIB_BUNDLE_URL).then(
  async (response) => {
    if (!response.ok) {
      throw new Error(
        `Could not download the TypeScript library files (HTTP ${response.status}). Run "npm run dev" or "npm run build", which generate them.`,
      );
    }
    return (await response.json()) as Record<string, string>;
  },
);

async function loadLib(fileName: string): Promise<string | undefined> {
  const bundle = await libBundle;
  return Object.hasOwn(bundle, fileName) ? bundle[fileName] : undefined;
}

function post(message: CompilerResponse) {
  self.postMessage(message);
}

const servicePromise: Promise<CompilerService> = (async () => {
  const [ts, libFiles] = await Promise.all([
    import("typescript").then(
      (m) => ("default" in m ? m.default : m) as typeof import("typescript"),
    ),
    loadLibFiles(LIB_FILES, loadLib),
  ]);
  const service = createCompilerService(ts, libFiles);
  // Warm up: parse the lib files once so the first real check is fast.
  service.check("export {};", "typescript");
  return service;
})();

servicePromise.then(
  (service) => post({ id: 0, type: "ready", version: service.version }),
  (error: unknown) =>
    post({
      id: 0,
      type: "init-error",
      message: error instanceof Error ? error.message : String(error),
    }),
);

self.addEventListener(
  "message",
  async (event: MessageEvent<CompilerRequest>) => {
    const request = event.data;
    if (
      !request ||
      typeof request !== "object" ||
      typeof request.id !== "number"
    )
      return;
    try {
      const service = await servicePromise;
      post({ id: request.id, type: "started" });
      if (request.type === "check") {
        post({
          id: request.id,
          type: "check",
          diagnostics: service.check(request.code, request.language),
        });
      } else if (request.type === "compile") {
        post({
          id: request.id,
          type: "compile",
          result: service.compile(request.code, request.language),
        });
      }
    } catch (error) {
      post({
        id: request.id,
        type: "error",
        message: error instanceof Error ? error.message : String(error),
      });
    }
  },
);
